  -- data/triggers/023/023_14_hell_trident_speech_trident_upgrades.lua
  (23, 14, $trig$-- Speech keywords: trident upgrades
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "trident") or string.find(string.lower(speech), "upgrades")) then
    return true  -- No matching keywords
end
wait(2)
local hellstep = actor:get_quest_stage("hell_trident")
local level
if hellstep == 1 then
    level = 65
elseif hellstep == 2 then
    level = 90
end
if (hellstep or 0) > 0 then
    -- switch on self.id
    -- switch on hellstage
    local response
    if hellstage == 1 then
        response = "stage2"
    elseif hellstage == 2 then
        response = "stage3"
    else
        if actor:get_has_completed("hell_trident") then
            response = "complete"
        end
    end
    local step = 1
    local spell1 = actor:get_has_completed("hellfire_brimstone")
    local spell2 = actor:get_has_completed("banish")
    if not actor:get_quest_var("hell_trident:helltask6") then
        if actor:get_quest_stage("vilekka_stew") > 3 then
            actor:set_quest_var("hell_trident", "helltask6", 1)
        end
    end
    local step = 2
    local spell1 = actor:get_has_completed("resurrection_quest")
    local spell2 = actor:get_has_completed("hell_gate")
    if hellstage == "phase" then
        if not actor:get_quest_var("hell_trident:helltask5") then
            if spell1 then
                actor:set_quest_var("hell_trident", "helltask5", 1)
            end
        end
        if not actor:get_quest_var("hell_trident:helltask4") then
            if spell2 then
                actor:set_quest_var("hell_trident", "helltask4", 1)
            end
        end
    end
    local response
    if actor:get_quest_stage("hell_trident") == "step" then
        if actor.level >= level then
            if (actor:get_quest_var("hell_trident:greet") or 0) == 0 then
                actor:set_quest_var("hell_trident", "greet", 1)
                if (self.zone_id == 60 and self.id == 32) then
                    actor:send("In the hissed whisper of ecstatic fervor " .. tostring(self.name) .. " says, 'Six thrice is the number of the greater demons.  Undertaking thus six and six, and six again, their interest can be piqued.'")
                    actor:send("</>")
                    actor:send("- Attempting to land <b:yellow>six and six and six</> in thrusts of your trident shall provide the pattern of the number.")
                    actor:send("</>")
                    actor:send("- <b:yellow>Six rubies, all uncut in nature, does double the signature.")
                    actor:send("</>")
                    actor:send("- Slay <b:yellow>six beings called angels</>, be they of any make or countenance, the number being counted thrice.")
                    actor:send("</>")
                    actor:send("- Sup on the grand powers of Hell to learn the most esoteric diablery.  Complete the quests for <b:yellow>Banish</> and <b:yellow>Hellfire and Brimstone</>.")
                    actor:send("</>")
                    actor:send("- Assist the High Priestess of Lolth in hunting down and destroying the heretics of her Goddess.")
                    wait(2)
                    actor:send(tostring(self.name) .. " says, 'In undertaking six in all will Hell be at your beck and call.'")
                elseif (self.zone_id == 125 and self.id == 26) then
                    actor:send(tostring(self.name) .. " says, 'Perhaps I will grant you a boon if you carry out sacrifices in my name.'")
                    actor:send("</>")
                    actor:send("- <b:yellow>Attack with " .. tostring(objects.template(23, 39).name) .. " 666 times</> as a sacrifice of power.")
                    actor:send("</>")
                    actor:send("- Bring me <b:yellow>six radiant rubies</> as a sacrifice of wealth.")
                    actor:send("</>")
                    actor:send("- Slay a combination of <b:yellow>six ghaeles, solars, or lesser seraphs</>.  Their suffering shall please me as a sacrifice of divinity.")
                    actor:send("</>")
                    actor:send("- Learn the most unholy of prayers.  Complete the quests for <b:yellow>Resurrection</> and <b:yellow>Hell Gate</> as a sacrifice of knowledge.")
                    actor:send("</>")
                    actor:send("- Finally, find one long-buried and branded an infidel.  <b:yellow>Finish his undying duel for him</> as a sacrifice of honor.")
                    wait(2)
                    actor:send(tostring(self.name) .. " says, 'Do this and I will lend you a greater share of my power.'")
                end
                wait(2)
                actor:send(tostring(self.name) .. " says, 'You can ask about your <b:cyan>[weapon progress]</> at any time.'")
            else
                actor:send(tostring(self.name) .. " says, 'Remember your six sacrifices.  Ask about your <b:cyan>[weapon progress]</> if you must.'")
            end
        else
            response = "level"
        end
    else
        if actor:get_has_completed("hell_trident") then
            response = "complete"
        elseif actor:get_quest_stage("hell_trident") < step then
            response = "stage1"
        else
            response = "stage3"
        end
    end
    if response == "stage1" then
        actor:send(tostring(self.name) .. " says, 'You must make the initial offerings with another dark priest.'")
    elseif response == "stage2" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'Hell hungers for more and will reward you greatly if you feed it.  Attack with that trident 666 times then seek out the Black Priestess, the left hand of Ruin Wormheart.  She will guide your offerings.'")
        else
            actor:send(tostring(self.name) .. " says, 'Other forces of Hell will eventually take notice of you too now.  Seek out the left hand of Ruin Wormheart, the Black Priestess, after you have grown more.  She will be your emissary.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "stage3" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'The Demon Lord Krisenna is known to traffic with mortals from time to time.  Impress him and perhaps he will grant you a boon.'")
        else
            actor:send(tostring(self.name) .. " says, 'Continue to prove your value to Hell and perhaps a Demon Lord might be willing to grant your their patronage.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "complete" then
        actor:send(tostring(self.name) .. " says, 'You've already marshalled the forces of Hell and Damnation to your side!'")
    elseif response == "level" then
        actor:send(tostring(self.name) .. " say, 'Stand before me again when you have achieved a larger measure of greatness.'")
        actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
    end
end$trig$, '630f58c447b1df5a94a6ecf02a40cd18'),
  -- data/triggers/028/028_07_waterform_wave_status_checker.lua
  (28, 7, $trig$-- Speech keywords: status status? progress progress?
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "status") or string.find(string.lower(speech), "status?") or string.find(string.lower(speech), "progress") or string.find(string.lower(speech), "progress?")) then
    return true  -- No matching keywords
end
wait(2)
local stage = actor:get_quest_stage("waterform")
if stage == 1 then
    self.room:send(tostring(self.name) .. " says, 'Find a piece of armor made of water to serve as the basis")
    self.room:send("</>of your new form.'")
elseif stage == 2 then
    self.room:send(tostring(self.name) .. " says, 'You need a special vessel to gather water in.  Kill")
    self.room:send("</>Tri-Aszp and get a large bone from her.'")
elseif stage == 3 then
    self.room:send(tostring(self.name) .. " says, 'You need a special vessel to gather water in.  Give me")
    self.room:send("</>the large bone from a grown white dragon so I can make you one.'")
elseif stage == 4 then
    local region1 = actor:get_quest_var("waterform:region1")
    local region2 = actor:get_quest_var("waterform:region2")
    local region3 = actor:get_quest_var("waterform:region3")
    local region4 = actor:get_quest_var("waterform:region4")
    local region5 = actor:get_quest_var("waterform:region5")
    self:say("Collect samples of living water from four different regions.")
    if region1 or region2 or region3 or region4 or region5 then
        -- (empty room echo)
        self.room:send("You already have samples from:")
        if region1 then
            self.room:send("- <blue>The Blue Fog trails and waters</>")
        end
        if region2 then
            self.room:send("- <blue>Nordus</>")
        end
        if region3 then
            self.room:send("- <blue>Layveran Labyrinth</>")
        end
        if region4 then
            self.room:send("- <blue>The Elemental Plane of Water</>")
        end
        if region5 then
            self.room:send("- <blue>The sunken castle</>")
        end
    end
    -- (empty room echo)
    local collected = (region1 and 1 or 0) + (region2 and 1 or 0) + (region3 and 1 or 0)
                    + (region4 and 1 or 0) + (region5 and 1 or 0)
    local samples = 4 - collected
    self.room:send("You need <b:blue>" .. tostring(samples) .. "</> more.")
elseif stage == 5 then
    self:say("Give me the cup so I can see the samples.")
elseif stage == 6 then
    -- Composite IDs match the keys written by 028_06.
    local water1 = actor:get_quest_var("waterform:32_96")
    local water2 = actor:get_quest_var("waterform:584_5")
    local water3 = actor:get_quest_var("waterform:533_19")
    local water4 = actor:get_quest_var("waterform:558_4")
    local water5 = actor:get_quest_var("waterform:587_1")
    local water6 = actor:get_quest_var("waterform:370_14")
    self:say("You are looking for six unique sources of water.")
    if water1 or water2 or water3 or water4 or water5 or water6 then
        -- (empty room echo)
        self.room:send("You have already analyzed water from:")
        if water1 then
            self.room:send("- <blue>a granite pool in the village of Mielikki</>")
        end
        if water2 then
            self.room:send("- <blue>a sparkling artesian well in the Realm of the King of Dreams</>")
        end
        if water3 then
            self.room:send("- <blue>a crystal clear fountain in the caverns of the Ice Cult</>")
        end
        if water4 then
            self.room:send("- <blue>the creek in the Eldorian Foothills</>")
        end
        if water5 then
            self.room:send("- <blue>the wishing well at the Dancing Dolphin in South Caelia</>")
        end
        if water6 then
            self.room:send("- <blue>an underground brook in the Minithawkin Mines</>")
        end
    end
    -- (empty room echo)
    self.room:send("You still need to analyze water from:")
    if not water1 then
        self.room:send("- <b:cyan>a granite pool in the village of Mielikki</>")
    end
    if not water2 then
        self.room:send("- <b:cyan>a sparkling artesian well in the Realm of the King of Dreams</>")
    end
    if not water3 then
        self.room:send("- <b:cyan>a crystal clear fountain in the caverns of the Ice Cult</>")
    end
    if not water4 then
        self.room:send("- <b:cyan>the creek in the Eldorian Foothills</>")
    end
    if not water5 then
        self.room:send("- <b:cyan>the wishing well at the Dancing Dolphin in South Caelia</>")
    end
    if not water6 then
        self.room:send("- <b:cyan>an underground brook in the Minithawkin Mines</>")
    end
elseif stage == 7 then
    self:say("Just return the cup to me and you're done!")
elseif actor:get_has_completed("waterform") then
    self:say("I already showed you how to transform into water.")
elseif (stage or 0) == 0 then
    self:say("But we're not doing anything together!")
end
if (stage or 0) > 0 and stage > 3 then
    -- (empty room echo)
    self.room:send(tostring(self.name) .. " says, 'If you need a new cup, say \"<b:yellow>I need a new cup</>\".'")
end$trig$, 'f2903246505f5acf944f2d56a8fff6c4'),
  -- data/triggers/028/028_10_waterform_cup_replacement.lua
  (28, 10, $trig$-- Match the full advertised phrase rather than any single keyword.
local speech_lower = string.lower(speech or "")
if not string.find(speech_lower, "new cup") then
    return true
end
wait(2)
local stage = actor:get_quest_stage("waterform")
if (stage or 0) > 0 and stage > 3 and actor:get_quest_var("waterform:new") ~= "yes" then
    actor:set_quest_var("waterform", "new", "yes")
    self:say("Oh no, you lost the cup??")
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'Well, I can make a new one, but you'll need to find the")
    self.room:send("</>base materials again.'")
    wait(2)
    self:say("Go find another acceptable dragon bone.")
end
return true$trig$, 'ed04bfc56c429c42a07936eaafb56de6'),
  -- data/triggers/030/030_09_erasmus_responds_to_charm_person.lua
  (30, 9, $trig$-- Converted from DG Script #3009: Erasmus responds to "charm person"
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
wait(2)
if string.find(actor.class, "illusionist") then
    if actor:get_skill("charm person") >= 1000 then
        self:say("A nice spell, isn't it?  I hope you're enjoying it.")
    elseif actor.level < 17 then
        self:say("Ah, charm person.  A powerful spell, capable of great evil - or good.")
        wait(2)
        self:say("Come back when you have a bit more experience, and I'll teach it to you.")
    else
        self:say("Oh, the charm person spell.  You're ready to learn that one!")
        wait(2)
        self:say("Stand still there while I teach you.")
        wait(2)
        self:emote("launches into a marathon of lectures and speeches about diverse arcana.")
        wait(5)
        self:emote("is still spewing forth obscure knowledge at a furious rate!")
        wait(5)
        self:emote("seems to be winding down, as if the lesson were almost over.")
        wait(5)
        if actor.room == self.room then
            self:say("I'm impressed with your attentiveness, " .. tostring(actor.name) .. ".")
            wait(3)
            self:say("I can see that you've learned charm person rather well.")
            skills.set_level(actor, "charm person", 1000)
        else
            self:say("Eh?  Where did " .. tostring(actor.name) .. " go?  Must not have a thirst for knowledge!")
        end
    end
elseif string.find(actor.class, "sorcerer") then
    if actor:get_skill("charm person") >= 1000 then
        self:command("gasp")
        wait(3)
        self:say("What's this?  An ordinary sorcerer with charm person?!")
        wait(5)
        self:say("Will wonders never cease!")
        wait(5)
        self:command("shake")
    else
        self:say("Don't look at me!  I'm a legendary teacher, but some things are just beyond me!")
        wait(5)
        self:say("You sorcerers require extra help learning this... rather simple spell.")
        wait(5)
        self:say("And you'll get none of it for me, because I have better things to do.")
    end
else
    self:command("sigh")
    wait(3)
    self:say("Yes, yes, a wonderful spell, how incredible we illusionists are, certainly.")
    wait(3)
    self:command("roll")
    wait(3)
    self:say("Why don't you go bash some poor rodents' heads in.  Or whatever it is you do.")
end$trig$, 'fcff51ab1bc6fb0a6df3ef25cca6fa2d'),
  -- data/triggers/030/030_160_skill_trainer_speach.lua
  (30, 160, $trig$-- Converted from DG Script #3160: ***skill trainer speach***
-- Original: MOB trigger, flags: SPEECH, SPEECH_TO, probability: 100%

-- Speech keywords: training yes backstab bludgeoning shadow slashing sneak steal switch throatcut track conceal corner double dual eye switch retreat hide pick piercing bandage douse lure cartwheel rend
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "training") or string.find(string.lower(speech), "yes") or string.find(string.lower(speech), "backstab") or string.find(string.lower(speech), "bludgeoning") or string.find(string.lower(speech), "shadow") or string.find(string.lower(speech), "slashing") or string.find(string.lower(speech), "sneak") or string.find(string.lower(speech), "steal") or string.find(string.lower(speech), "switch") or string.find(string.lower(speech), "throatcut") or string.find(string.lower(speech), "track") or string.find(string.lower(speech), "conceal") or string.find(string.lower(speech), "corner") or string.find(string.lower(speech), "double") or string.find(string.lower(speech), "dual") or string.find(string.lower(speech), "eye") or string.find(string.lower(speech), "switch") or string.find(string.lower(speech), "retreat") or string.find(string.lower(speech), "hide") or string.find(string.lower(speech), "pick") or string.find(string.lower(speech), "piercing") or string.find(string.lower(speech), "bandage") or string.find(string.lower(speech), "douse") or string.find(string.lower(speech), "lure") or string.find(string.lower(speech), "cartwheel") or string.find(string.lower(speech), "rend")) then
    return true  -- No matching keywords
end
wait(2)
-- make sure they have a quest record for saving variables
if actor:get_quest_stage("trainer_3160") < 1 then
    actor:start_quest("trainer_3160")
else
    actor:erase_quest("trainer_3160")
    actor:start_quest("trainer_3160")
end
-- introductions: lists the skills available
if speech == "training?" or speech == "training" or speech == "yes" then
    self.room:send(tostring(self.name) .. " says, 'Sure, I can help you improve just about any necessary stealthy")
    self.room:send("</>talent.  But remember, I can't teach you skills you don't already know.'")
    -- (empty room echo)
    self.room:send("</>Just ask me about a skill, and I'll give you a quote:")
    -- (empty room echo)
    self.room:send("</>backstab, bandage, bludgeoning weapons, cartwheel, conceal, corner")
    self.room:send("</>double attack, douse, dual wield, eye gouge, group retreat, hide, lure, pick lock,")
    self.room:send("</>piercing weapons, rend, retreat, shadow, slashing weapons, sneak, sneak attack,")
    self.room:send("</>steal, switch, throatcut, track.")
    return _return_value
else
    -- defining variables for this script
    local name = actor.name
    local cha = actor.real_cha
    local int = actor.real_int
    -- 
    -- Identify the skill to be trained
    local skill, word2
    if speech == "backstab" then
        skill = actor:get_skill("backstab")
    elseif speech == "bludgeoning weapons" then
        skill = actor:get_skill("bludgeoning weapons")
        word2 = "weapons"
    elseif speech == "cartwheel" then
        skill = actor:get_skill("cartwheel")
    elseif speech == "conceal" then
        skill = actor:get_skill("conceal")
    elseif speech == "corner" then
        skill = actor:get_skill("corner")
    elseif speech == "double attack" then
        skill = actor:get_skill("double attack")
        word2 = "attack"
    elseif speech == "dual wield" then
        skill = actor:get_skill("dual wield")
        word2 = "wield"
    elseif speech == "eye gouge" then
        word2 = "gouge"
        skill = actor:get_skill("eye gouge")
    elseif speech == "group retreat" then
        word2 = "retreat"
        skill = actor:get_skill("group retreat")
    elseif speech == "hide" then
        skill = actor:get_skill("hide")
    elseif speech == "instant kill" then
        skill = actor:get_skill("instant kill")
        word2 = "kill"
    elseif speech == "lure" then
        skill = actor:get_skill("lure")
    elseif speech == "pick lock" then
        skill = actor:get_skill("pick lock")
        word2 = "lock"
    elseif speech == "piercing weapons" then
        skill = actor:get_skill("piercing weapons")
        word2 = "weapons"
    elseif speech == "rend" then
        skill = actor:get_skill("rend")
    elseif speech == "retreat" then
        skill = actor:get_skill("retreat")
    elseif speech == "shadow" then
        skill = actor:get_skill("shadow")
    elseif speech == "slashing weapons" then
        skill = actor:get_skill("slashing weapons")
        word2 = "weapons"
    elseif speech == "sneak" then
        skill = actor:get_skill("sneak")
    elseif speech == "sneak attack" then
        skill = actor:get_skill("sneak attack")
        word2 = "attack"
    elseif speech == "steal" then
        skill = actor:get_skill("steal")
    elseif speech == "switch" then
        skill = actor:get_skill("switch")
    elseif speech == "throatcut" then
        skill = actor:get_skill("throatcut")
    elseif speech == "track" then
        skill = actor:get_skill("track")
    elseif speech == "bandage" then
        skill = actor:get_skill("bandage")
    elseif speech == "douse" then
        skill = actor:get_skill("douse")
    else
        self:say("I'm not familiar with " .. tostring(speech) .. ".")
        return _return_value
    end
    -- 
    -- Check to see if a skill should be taught at all
    -- 
    -- get_skill is the 0..1000 proficiency (DG %actor.skill[]% was 0..100, hence its `10 *`)
    skill = skill or 0
    local maxskill = actor.level * 10 + 60
    -- check for capped skills
    local cap = 1000
    if speech == "track" then
        -- switch on actor.class
        if actor.class == "mercenary" then
            cap = 850
        elseif actor.class == "rogue" then
            cap = 650
        elseif actor.class == "thief" then
            cap = 600
        elseif actor.class == "assassin" then
            cap = 750
        end
    elseif speech == "dodge" or speech == "parry" then
        -- switch on actor.race
        if actor.race == "ogre" or actor.race == "troll" then
            cap = 700
        end
    elseif speech == "riposte" then
        -- switch on actor.race
        if actor.race == "ogre" then
            cap = 700
        end
    end
    if skill < 50 then
        self.room:send(tostring(self.name) .. " says, 'I wouldn't know where to start.")
        self.room:send("</>Let's talk about improving a skill you actually know.'")
        return _return_value
    elseif skill >= cap or skill >= maxskill then
        self:say("There is nothing left to teach you. You've mastered " .. tostring(speech) .. "!")
        return _return_value
    end
    if cap < maxskill then
        maxskill = cap
    end
    -- This portion is for smooth speech indicating the effects of a players cha or int
    self:command("score")
    if cha > 70 then
        self:say("I like you.")
        if int > 70 then
            -- (empty room echo)
            self.room:send(tostring(self.name) .. " says, '...and you're pretty bright.")
            self.room:send("</>I'll give you a good deal.'")
        elseif int < 50 then
            -- (empty room echo)
            self:say("..but you aren't the smartest.")
        end
    elseif cha < 50 then
        self:say("I don't like you much.")
        if int > 70 then
            -- (empty room echo)
            self:say("...but you are pretty bright.")
        elseif int < 50 then
            -- (empty room echo)
            self:say("...and you aren't the smartest.")
        else
        end
    else
        self:say("You're alright.")
        if int > 70 then
            -- (empty room echo)
            self:say("...and you're pretty bright.")
        elseif int < 50 then
            -- (empty room echo)
            self:say("...but you aren't the smartest.")
        end
    end
    -- (empty room echo)
    -- Now a price is calculated
    local change = maxskill - skill
    local opinion = 200 - (cha + int)
    local price = math.floor(change * opinion * actor.level * actor.level / (skill * 20))
    -- 
    -- now the price in copper has to be divided into coinage.
    local plat = price // 1000
    local gold = price // 100 - plat * 10
    local silv = price // 10 - plat * 100 - gold * 10
    local copp = price  - plat * 1000 - gold * 100 - silv * 10
    -- now the price can be reported
    self:say("I'll teach you " .. tostring(speech) .. " for " .. tostring(plat) .. " platinum, " .. tostring(gold) .. " gold, " .. tostring(silv) .. " silver, " .. tostring(copp) .. " copper.")
    -- (empty room echo)
    self:say("Just bring me the money when you're ready to practice.")
    actor:set_quest_var("trainer_3160", "skill_name", speech)
    if word2 then
        actor:set_quest_var("trainer_3160", "word2", word2)
    end
    actor:set_quest_var("trainer_3160", "skill_level", skill)
    actor:set_quest_var("trainer_3160", "max_skill", maxskill)
    actor:set_quest_var("trainer_3160", "price", price)
    actor:set_quest_var("trainer_3160", "actor_level", actor.level)
end$trig$, '8173a97c9786eb02838d03e100385f5b'),
  -- data/triggers/030/030_161_pay_for_training.lua
  (30, 161, $trig$-- Converted from DG Script #3161: pay for training
-- Original: MOB trigger, flags: BRIBE, num_arg: 1 (minimum bribe in copper)

local _return_value = true  -- Default: allow action
local full_skill
if actor:get_quest_var("trainer_3160:word2") then
    full_skill = tostring(actor:get_quest_var("trainer_3160:skill_name")) .. " " .. tostring(actor:get_quest_var("trainer_3160:word2"))
elseif actor:get_quest_var("trainer_3160:skill_name") then
    full_skill = actor:get_quest_var("trainer_3160:skill_name")
end
wait(1)
if actor:get_quest_var("trainer_3160:actor_level") == actor.level then
    if value >= actor:get_quest_var("trainer_3160:price") then
        self:command("grin " .. tostring(actor.name))
        wait(1)
        actor:send(tostring(self.name) .. " says, 'Fantastic. Let's get started...'")
        wait(5)
        actor:send("Some time passes...")
        wait(3)
        actor:send("You feel you are getting the hang of things.")
        wait(3)
        actor:send("You feel your skill in " .. tostring(full_skill) .. " improving dramatically!")
        -- Legacy mskillset: the maximum proficiency the trainer quoted (level and class capped).
        skills.set_level(actor, full_skill, actor:get_quest_var("trainer_3160:max_skill") or 1000)
        actor:erase_quest("trainer_3160")
    else
        actor:send(tostring(self.name) .. " says, 'I appreciate your voluntary donation, but I'm afraid that's all it was.'")
        self:command("snicker " .. tostring(actor))
        actor:send("</>")
        actor:send(tostring(self.name) .. " says, 'I don't accept installments.  It's got to be all up front.'")
    end
else
    _return_value = true
    wait(2)
    self:command("consider " .. tostring(actor))
    wait(2)
    self:command("ponder")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'Something's different about you.  What skill were you going to train again?'")
    actor:erase_quest("trainer_3160")
end
return _return_value$trig$, '8956c0cd3930ec9e763eaf464b36fb01'),
