                wait(4)
                actor:send(tostring(self.name) .. " says, 'Do you feel strong enough to handle that?'")
            end
            if actor:get_quest_var("beast_master:hunt") == "running" then
            elseif actor:get_quest_stage("beast_master") == 3 then
