  (53, 45, $trig$-- Converted from DG Script #5345: Elemental Chaos Hakujo new mission
-- Original: MOB trigger, flags: SPEECH, probability: 0%

-- Speech phrase: I need a new note (DG num_arg 0 = the speech contains the phrase, not a chance)
if not string.find(string.lower(speech), "i need a new note", 1, true) then
    return true  -- Not the phrase
end
wait(2)
if actor.level >= (actor:get_quest_stage("elemental_chaos") - 1) * 10 then
    if (actor:get_quest_var("elemental_chaos:bounty") or 0) ~= 0 then
        -- switch on actor:get_quest_stage("elemental_chaos")
        local mission
        if actor:get_quest_stage("elemental_chaos") == 1 then
            mission = 20
        elseif actor:get_quest_stage("elemental_chaos") == 2 then
            mission = 21
        elseif actor:get_quest_stage("elemental_chaos") == 3 then
            mission = 22
        elseif actor:get_quest_stage("elemental_chaos") == 4 then
            mission = 23
        elseif actor:get_quest_stage("elemental_chaos") == 5 then
            mission = 24
        elseif actor:get_quest_stage("elemental_chaos") == 6 then
            mission = 25
        elseif actor:get_quest_stage("elemental_chaos") == 7 then
            mission = 26
        elseif actor:get_quest_stage("elemental_chaos") == 8 then
            mission = 27
        elseif actor:get_quest_stage("elemental_chaos") == 9 then
            mission = 28
        elseif actor:get_quest_stage("elemental_chaos") == 10 then
            mission = 29
        end
        self:command("grumble")
        self.room:spawn_object(53, mission)
        self:command("give mission " .. tostring(actor))
        actor:send(tostring(self.name) .. " says, 'Be more careful next time.'")
    end
end$trig$, '83fd484079adba011334f268db6fbc7d'),
  -- data/triggers/053/053_54_monk_chants_hakujo_speech_chants.lua
  (53, 54, $trig$-- Converted from DG Script #5354: Monk Chants Hakujo Speech chants
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: chant chants
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "chant") or string.find(string.lower(speech), "chants")) then
    return true  -- No matching keywords
end
wait(2)
if actor:get_quest_stage("monk_vision") >= 3 then
    if actor:get_quest_stage("monk_chants") == 0 then
        actor:send(tostring(self.name) .. " says, 'As you walk your path to enlightenment, your mind's capacity for esoteric knowledge will vastly increase.  This knowledge forms the basis for many powerful chants and hymns.'")
        wait(2)
        actor:send(tostring(self.name) .. " says, 'Each new vision marking represents your readiness for a new chant.  Much like the vision quests you undertake, you will need to find a source of knowledge and meditate on it in a place of great resonance.'")
        actor:start_quest("monk_chants")
        wait(2)
    end
    local decline
    if actor:get_quest_stage("monk_chants") == 1 then
        if actor.level >= 30 then
            actor:send(tostring(self.name) .. " says, 'The first esoteric chant you can learn is the <b:yellow>Tremors of Saint Augustine</>.  This prayer will channel the forces of the earth through your hands, allowing you to disintegrate your foes with your touch.'")
            wait(4)
            actor:send(tostring(self.name) .. " says, 'The secrets of this chant are contained in <b:yellow>a book surrounded by trees and shadows</>.  To understand the deeper truth, you must find this book and <b:cyan>[meditate]</> in <b:yellow>a place that is both natural and urban, serenely peaceful and profoundly sorrowful</>.'")
            wait(4)
            actor:send(tostring(self.name) .. " says, 'I cannot be more specific than this.  You must prove your capabilities and solve the puzzle on your own.  Do so and you will gain the knowledge of the Tremors of Saint Augustine.'")
            wait(2)
            self:command("bow " .. tostring(actor))
        else
            decline = "level"
        end
    elseif actor:get_quest_stage("monk_chants") == 2 then
        if actor:get_quest_stage("monk_vision") > 4 then
            if actor.level >= 40 then
                actor:send(tostring(self.name) .. " says, 'Waiting for you next is the <b:yellow>Tempest of Saint Augustine</>.  This prayer will channel the electrical might of the storm through your fists.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'There is <b:yellow>a scroll dedicated to this particular chant, guarded by a creature of the same elemental affinity</>.  <b:cyan>[Meditate]</> on it at <b:yellow>the peak of Urchet Pass</> and you will gain the knowledge of the chant.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                decline = "level"
            end
        else
            decline = "vision"
        end
    elseif actor:get_quest_stage("monk_chants") == 3 then
        if actor:get_quest_stage("monk_vision") > 5 then
            if actor.level >= 50 then
                actor:send(tostring(self.name) .. " says, 'You are ready for a third prayer to Saint Augustine.  This prayer will call the howling force of the blizzard, freezing anything you touch.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'Knowledge of ice and snow is kept in <b:yellow>a book held by a master who in turn is a servant of a beast of winter</>.  The secrets of the book can be revealed through <b:cyan>[meditating]</> in <b:yellow>a temple shrouded in mists</>.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'Complete this meditation and the <b:yellow>Blizzards of Saint Augustine</> will be revealed to you.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                decline = "level"
            end
        else
            decline = "vision"
        end
    elseif actor:get_quest_stage("monk_chants") == 4 then
        if actor:get_quest_stage("monk_vision") > 6 then
            if actor.level >= 60 then
                actor:send(tostring(self.name) .. " says, 'Words are powerful weapons.  Properly intoned, words can be as devastating as any sword.  The <b:yellow>Aria of Dissonance</> is a mystical weapon of war that monks can unleash to descimate their opponent's defenses.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'As a tool of war, the secrets are deeply encoded in <b:yellow>a book on war, held by a banished war god</>.  They can be understood only by <b:cyan>[meditating]</> on them in <b:yellow>a dark cave before a blasphemous book, near an unholy fire</>.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                decline = "level"
            end
        else
            decline = "vision"
        end
    elseif actor:get_quest_stage("monk_chants") == 5 then
        if actor:get_quest_stage("monk_vision") > 7 then
            if actor.level >= 75 then
                actor:send(tostring(self.name) .. " says, 'To augment the growth of the mind, it is important to understand the self is but a multifaceted illusion.  Understanding that will allow you to manipulate that illusion to provoke others to attacking you.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'There is <b:yellow>a scroll where this revelation is inscribed over and over held by a brother who thirsts for escape</>.  Give him what he most desires to earn the scroll.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'With the scroll in hand, <b:cyan>[meditate]</> on it in <b:yellow>a chapel of the walking dead</> to hear the music that lays beyond the end of all things, the <b:yellow>Apocalyptic Anthem</>.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                decline = "level"
            end
        else
            decline = "vision"
        end
    elseif actor:get_quest_stage("monk_chants") == 6 then
        if actor:get_quest_stage("monk_vision") > 8 then
            if actor.level >= 80 then
                actor:send(tostring(self.name) .. " says, 'You are ready for the final prayer to Saint Augustine.  This prayer will allow you to hold fire in your hands, making you a living inferno.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'Fire is both a blessing and a curse.  It provides heat vital to life and can incinerate life just as easily.  This duality is reflected in <b:yellow>scrolls of curses, carried by children of air in a floating fortress</>.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'Take one of these scrolls to <b:yellow>an altar dedicated to fire's destructive forces</> and <b:cyan>[meditate]</> to unleash the power of the <b:yellow>Fires of Saint Augustine</>.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                decline = "level"
            end
        else
            decline = "vision"
        end
    elseif actor:get_quest_stage("monk_chants") == 7 then
        if actor:get_quest_stage("monk_vision") > 9 then
            if actor.level >= 99 then
                actor:send(tostring(self.name) .. " says, 'The final esoteric chant is the ability to plant the seed of doubt in an opponent's very core, shattering the false reality that is corporeal form.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'The chant is the ultimate weaponization of revenge.  An eye for an eye, as the saying goes, is the ultimately symbol of revenge.  Cut out the <b:yellow>eye of one caught in an eternal feud</>.  Bring it to <b:yellow>an altar deep in the outer realms surrounded by those who's vengeance was never satisfied</>.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, '<b:cyan>[meditate]</> on the illusory satisfaction of what revenge makes one think is certain to understand the doubt that is the <b:yellow>Seed of Destruction</>.'")
                wait(2)
                self:command("bow " .. tostring(actor))
            else
                actor:send(tostring(self.name) .. " says, 'Unfortunately you must reach the pinnacle of mortal experience before you are ready to grasp this final chant.'")
                return _return_value
            end
        else
            decline = "vision"
        end
    end
    if decline == "level" then
        actor:send(tostring(self.name) .. " says, 'You must gain more practical experience before you can take on more esoteric experience.'")
    elseif decline == "vision" then
        actor:send(tostring(self.name) .. " says, 'You must first take another step towards <b:cyan>[enlightenment]</> before you can grasp more esoteric knowledge.'")
    end
end$trig$, '311b249c0ecc120d2f1c945352aead70'),
  -- data/triggers/053/053_57_hell_trident_progress_tracker.lua
  (53, 57, $trig$-- Converted from DG Script #5357: Hell Trident progress tracker
-- Original: MOB trigger, flags: SPEECH, probability: 0%

-- Speech phrase: weapon progress (DG num_arg 0 = the speech contains the phrase, not a chance)
if not string.find(string.lower(speech), "weapon progress", 1, true) then
    return true  -- Not the phrase
end
wait(2)
if string.find(actor.class, "diabolist") then
    local level, response
    if actor:get_quest_stage("hell_trident") > 0 then
        local hellstage = actor:get_quest_stage("hell_trident")
        if hellstage == 1 then
            level = 65
        elseif hellstage == 2 then
            level = 90
        end
        -- switch on self.id
        -- switch on hellstage
        if hellstage == 1 then
            response = "stage2"
        elseif hellstage == 2 then
            response = "stage3"
        else
            if actor:get_has_completed("hell_trident") then
                response = "complete"
            end
        end
        local step = 1
        local gem = 55662
        local pl_word = "angels"
        local word = "angel"
        local spell1 = "Hellfire and Brimstone"
        local quest1 = actor:get_has_completed("hellfire_brimstone")
        local spell2 = "Banish"
        local quest2 = actor:get_has_completed("banish")
        if not actor:get_quest_var("hell_trident:helltask6") and actor.level >= level and hellstage == 1 then
            if actor:get_quest_stage("vilekka_stew") > 3 then
                actor:set_quest_var("hell_trident", "helltask6", 1)
            end
        end
        local task6 = "assisted Vilekka Kar'Shezden"
        local task6do = "&3&bAssist the High Priestess of Lolth in hunting down and destroying the heretics of her Goddess.&0"
        local step = 2
        local gem = 55739
        local pl_word = "ghaeles, solars, or seraphs"
        local word = "ghaele, solar, or seraph"
        local spell1 = "Resurrect"
        local quest1 = actor:get_has_completed("resurrection_quest")
        local spell2 = "Hell Gate"
        local quest2 = actor:get_has_completed("hell_gate")
        local task6 = "Defeated the Undead Prince"
        local task6do = "find one long-buried and branded an infidel.  &3&bFinish his undying duel for him&0 as a sacrifice of honor."
        if hellstage == "step" then
            if actor.level >= level then
                if not actor:get_quest_var("hell_trident:helltask4") then
                    if quest1 then
                        actor:set_quest_var("hell_trident", "helltask4", 1)
                    end
                end
                if not actor:get_quest_var("hell_trident:helltask5") then
                    if quest2 then
                        actor:set_quest_var("hell_trident", "helltask5", 1)
                    end
                end
                if (actor:get_quest_var("hell_trident:greet") or 0) == 0 then
                    actor:send(tostring(self.name) .. " says, 'Tell me why you have come.'")
                else
                    local job1 = actor:get_quest_var("hell_trident:helltask1")
                    local job2 = actor:get_quest_var("hell_trident:helltask2")
                    local job3 = actor:get_quest_var("hell_trident:helltask3")
                    local job4 = actor:get_quest_var("hell_trident:helltask4")
                    local job5 = actor:get_quest_var("hell_trident:helltask5")
                    local job6 = actor:get_quest_var("hell_trident:helltask6")
                    if job1 or job2 or job3 or job4 or job5 or job6 then
                        actor:send(tostring(self.name) .. " says, 'You have done the following:'")
                        if job1 then
                            actor:send("- attacked 666 times")
                        end
                        if job2 then
                            actor:send("- slayed 6 " .. tostring(pl_word))
                        end
                        if job3 then
                            actor:send("- found 6 " .. "%get.obj_shortdesc[%gem%]%")
                        end
                        if job4 then
                            actor:send("- learned " .. tostring(spell1))
                        end
                        if job5 then
                            actor:send("- learned " .. tostring(spell2))
                        end
                        if job6 then
                            actor:send("- " .. tostring(task6))
                        end
                        actor:send("</>")
                    end
                    if job1 and job2 and job3 and job4 and job5 and job6 then
                        actor:send(tostring(self.name) .. " says, 'Give me your trident to finalize the pact.'")
                    else
                        actor:send("You must still:")
                        if not job1 then
                            local remaining = 666 - actor:get_quest_var("hell_trident:attack_counter")
                            if remaining > 1 then
                                actor:send("- <b:yellow>attack " .. tostring(remaining) .. " more times with your trident</>")
                            else
                                actor:send("- <b:yellow>attack " .. tostring(remaining) .. " more time with your trident</>")
                            end
                        end
                        if not job2 then
                            local kills = 6 - actor:get_quest_var("hell_trident:celestials")
                            if kills > 1 then
                                actor:send("- <b:yellow>slay " .. tostring(kills) .. " more " .. tostring(pl_word) .. "</>")
                            else
                                actor:send("- <b:yellow>slay " .. tostring(kills) .. " more " .. tostring(word) .. "</>")
                            end
                        end
                        if not job3 then
                            local gems = 6 - actor:get_quest_var("hell_trident:gems")
                            if gems > 1 then
                                actor:send("- <b:yellow>find " .. tostring(gems) .. " more " .. "%get.obj_pldesc[%gem%]%</>")
                            else
                                actor:send("- <b:yellow>find " .. tostring(gems) .. " more " .. "%get.obj_noadesc[%gem%]%</>")
                            end
                        end
                        if not job4 then
                            actor:send("- <b:yellow>learn " .. tostring(spell1) .. "</>")
                        end
                        if not job5 then
                            actor:send("- <b:yellow>learn " .. tostring(spell2) .. "</>")
                        end
                        if not job6 then
                            actor:send("- " .. tostring(task6do))
                        end
                    end
                end
            else
                response = "level"
            end
        else
            if actor:get_has_completed("hell_trident") then
                response = "complete"
            elseif actor:get_quest_stage("hell_trident") < step then
                response = "stage1"
            else
                response = "stage3"
            end
        end
    end
    if response == "stage1" then
        actor:send(tostring(self.name) .. " says, 'You must make the initial offerings with another dark priest.'")
    elseif response == "stage2" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'Hell hungers for more and will reward you greatly if you feed it.  Attack with that trident 666 times then seek out the Black Priestess, the left hand of Ruin Wormheart.  She will guide your offerings.'")
        else
            actor:send(tostring(self.name) .. " says, 'Other forces of Hell will eventually take notice of you too now.  Seek out the left hand of Ruin Wormheart, the Black Priestess, after you have grown more.  She will be your emissary.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "stage3" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'The Demon Lord Krisenna is known to traffic with mortals from time to time.  Impress him and perhaps he will grant you a boon.'")
        else
            actor:send(tostring(self.name) .. " says, 'Continue to prove your value to Hell and perhaps a Demon Lord might be willing to grant your their patronage.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "complete" then
        actor:send(tostring(self.name) .. " says, 'You've already marshalled the forces of Hell and Damnation to your side!'")
    elseif response == "level" then
        actor:send(tostring(self.name) .. " say, 'Stand before me again when you have achieved a larger measure of greatness.'")
        actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
    end
end$trig$, 'd29b950a24caefa45d11bad86312599d'),
  -- data/triggers/060/060_50_berix_bounty_hunt_greet.lua
  (60, 50, $trig$-- Converted from DG Script #6050: Berix bounty hunt greet
-- Original: MOB trigger, flags: GREET_ALL, probability: 100%
wait(2)
if not actor:get_has_completed("bounty_hunt") then
    if actor:get_quest_stage("bounty_hunt") == 0 then
        if actor.alignment <= -350 or string.find(actor.class, "assassin") or string.find(actor.class, "mercenary") then
            actor:send(tostring(self.name) .. " says, 'Well hello there.  You look like quite a piece of work.  I think I have a <b:cyan>[job]</> for you.'")
        else
            actor:send(tostring(self.name) .. " says, 'What do you want?'")
        end
    elseif actor:get_quest_var("bounty_hunt:bounty") == "running" then
        actor:send(tostring(self.name) .. " says, 'You're still on the hunt.  What are you doing here?  If you lost your contract like a moron, say, <b:cyan>\"I need a new contract\"</>.'")
    elseif actor:get_quest_var("bounty_hunt:bounty") == "dead" then
        actor:send(tostring(self.name) .. " says, 'If you got the job done, give me your contract.  If you lost your contract like a moron, say, <b:cyan>\"I need a new contract\"</>.'")
    elseif actor:get_quest_stage("bounty_hunt") >= 1 and not actor:get_has_completed("bounty_hunt") then
        actor:send(tostring(self.name) .. " says, 'Ah, back for another <b:cyan>[job]</> I see.'")
    end
    if not actor:get_has_completed("assassin_mask") and actor.level > 9 and string.find(actor.class, "assassin") then
        wait(1)
        actor:send(tostring(self.name) .. " says, 'Or maybe you're here to discuss a <b:cyan>[promotion]</>.'")
    end
else
    if string.find(actor.class, "assassin") and actor:get_quest_stage("assassin_mask") == 0 and actor.level > 9 then
        actor:send(tostring(self.name) .. " says, 'Oh look, someone else in line for a <b:cyan>[promotion]</>.'")
    elseif actor:get_quest_stage("assassin_mask") > 0 and not actor:get_has_completed("assassin_mask") then
        actor:send(tostring(self.name) .. " says, 'Ah, you must be looking for another <b:cyan>[promotion]</>.'")
    end
end$trig$, 'ada686be7b564dbf5d4d574d2cd0a791'),
  -- data/triggers/060/060_51_berix_bounty_hunt_speech.lua
  (60, 51, $trig$-- Converted from DG Script #6051: Berix bounty hunt speech
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: job jobs what contract contracts
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "job") or string.find(string.lower(speech), "jobs") or string.find(string.lower(speech), "what") or string.find(string.lower(speech), "contract") or string.find(string.lower(speech), "contracts")) then
    return true  -- No matching keywords
end
wait(2)
if actor:get_has_completed("bounty_hunt") then
    actor:send(tostring(self.name) .. " says, 'You know, I'm fresh out of work for you.  Good luck!'")
elseif actor:get_quest_stage("bounty_hunt") == 0 or (actor:get_quest_stage("bounty_hunt") == 1 and (actor:get_quest_var("bounty_hunt:bounty") or 0) == 0) then
    actor:send(tostring(self.name) .. " says, 'Sure, I have something easy to start with.'")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'I have benefactors who would like certain individuals to... disappear.  The resulting chaos is to their benefit.  They're willing to pay handsomely for that to occur.  Ours is not ask questions but simply see that it happen.'")
    wait(4)
    actor:send(tostring(self.name) .. " says, 'One such individual is the king of some cat colony or somme such down near the town of Mielikki.  I don't know why they say he's \"merely\" a king, but again, our job isn't to ask questions.'")
    wait(4)
    actor:send(tostring(self.name) .. " says, 'Can I count on you to get this done?'")
elseif actor:get_quest_var("bounty_hunt:bounty") == "dead" then
    actor:send(tostring(self.name) .. " says, 'Give me your current contract first.'")
    return _return_value
else
    if actor.level >= (actor:get_quest_stage("bounty_hunt") - 1) * 10 then
        -- switch on actor:get_quest_stage("bounty_hunt")
        if actor:get_quest_var("bounty_hunt:bounty") == "running" then
            if actor:get_quest_stage("bounty_hunt") == 1 then
                actor:send(tostring(self.name) .. " says, 'You still have a job to do.  Best get on killing that cat-king or whatever first.'")
            end
            if actor:get_quest_var("bounty_hunt:bounty") == "running" then
            elseif actor:get_quest_stage("bounty_hunt") == 2 then
                actor:send(tostring(self.name) .. " says, 'You still have a job to do.  Take out the Noble and the Abbot sheltering him at the Abbey of St. George.'")
            else
                actor:send(tostring(self.name) .. " says, 'There's a noble who's gone into hiding because a lot of people want him dead.  But good news: I've been able to locate him!  He's hiding in the Abbey of St. George.'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'I've got someone who's so angry, they're asking us to kill not just the noble, but the Abbot who took him in!  Double payday!'")
                wait(3)
                actor:send(tostring(self.name) .. " says, 'You in?'")
            end
            if actor:get_quest_var("bounty_hunt:bounty") == "running" then
            elseif actor:get_quest_stage("bounty_hunt") == 3 then
                actor:send(tostring(self.name) .. " says, 'You still have a job to do.  Take out the three Chieftains in the southwestern Highlands.'")
            else
                actor:send(tostring(self.name) .. " says, 'There are three warring clans down in the Highlands past the Gothra Desert: O'Connor, McLeod, and Cameron.  Each has taken out a contract on the other, but get this: they all paid in advance!'")
                wait(4)
                actor:send(tostring(self.name) .. " says, 'It's a big job, but it'll be totally worth it if we pull it off.  And it'll be a legendary triple-cross!  Think of how impressive that'll be!'")
                wait(3)
                actor:send(tostring(self.name) .. " says, 'So whadda ya say?'")
            end
            if actor:get_quest_var("bounty_hunt:bounty") == "running" then
            elseif actor:get_quest_stage("bounty_hunt") == 4 then
                actor:send(tostring(self.name) .. " says, 'You still have a job to do.  Find the Frakati Leader and kill him.'")
            else
                actor:send(tostring(self.name) .. " says, 'I've got a challenge for you.  There's a hidden reservation near the town of Mielikki for a group of tribal hunters.'")
                wait(4)
