    elseif maskstage == 4 then
        mask = 10304
        gem = 55638
        place = "Dark Chamber"
        hint = "hidden below a ghostly fortress."
    elseif maskstage == 5 then
        mask = 16200
        gem = 55666
        place = "Darkness......"
