        gem = 55675
        place = "Surrounded by Darkness"
        hint = "in a volcanic shaft."
    elseif maskstage == 7 then
        mask = 51075
        gem = 55693
        place = "Dark Indecision"
        hint = "before an altar in a fallen maze."
    elseif maskstage == 8 then
