  -- data/triggers/062/062_93_gem_exchange_set_type.lua
  (62, 93, $trig$-- Speech keywords trigger any gem-related word
local s = string.lower(speech)
local gems = {
    "amber", "agate", "amethyst", "aquamarine", "beryl", "bloodstone", "blood",
    "carnelian", "citrine", "diamond", "emerald", "garnet", "hematite", "jade",
    "jasper", "labradorite", "lapis", "lazuli", "lapis-lazuli", "malachite",
    "moonstone", "moon", "onyx", "opal", "pearl", "peridot", "sapphire", "ruby",
    "topaz", "tourmaline", "turquoise",
}
local matched = false
for _, g in ipairs(gems) do
    if string.find(s, g) then matched = true; break end
end
if not matched then
    return true
end

wait(2)
if actor:get_quest_stage("gem_exchange") == 0 or actor:get_quest_stage("gem_exchange") == 0 then
    actor:start_quest("gem_exchange")
end

-- Quality grade selectors. Order matters: more-specific words first so
-- "crushed amber" doesn't get classified as plain "amber".
local function grade()
    if string.find(s, "crushed") then return "crushed"
    elseif string.find(s, "dust") then return "dust"
    elseif string.find(s, "uncut") then return "uncut"
    elseif string.find(s, "flawed") then return "flawed"
    elseif string.find(s, "shard") then return "shard"
    elseif string.find(s, "enchanted") then return "enchanted"
    elseif string.find(s, "radiant") then return "radiant"
    elseif string.find(s, "perfect") then return "perfect"
    end
    return "polished"
end

-- gem_table[stone_keyword][grade] -> legacy vnum.
-- A nil value means that grade is not stocked for that gemstone.
local gem_table = {
    amber = { crushed=55575, dust=55567, uncut=55602, flawed=55624, shard=55583, enchanted=55723, radiant=55701, perfect=55679, polished=55646 },
    agate = { uncut=55599, flawed=55621, perfect=55676, radiant=55698, enchanted=55720, polished=55643 },
    amethyst = { crushed=55574, dust=55566, uncut=55601, flawed=55623, shard=55582, enchanted=55722, radiant=55700, perfect=55678, polished=55645 },
    aquamarine = { crushed=55579, dust=55571, uncut=55613, flawed=55635, shard=55587, enchanted=55734, radiant=55712, perfect=55690, polished=55657 },
    beryl = { uncut=55606, flawed=55628, shard=55605, enchanted=55727, radiant=55705, perfect=55683, polished=55650 },
    bloodstone = { uncut=55598, flawed=55620, perfect=55675, radiant=55697, enchanted=55719, polished=55642 },
    carnelian = { uncut=55595, flawed=55617, perfect=55672, radiant=55694, enchanted=55716, polished=55639 },
    citrine = { crushed=55577, dust=55569, uncut=55604, flawed=55626, shard=55585, enchanted=55725, radiant=55703, perfect=55681, polished=55648 },
    diamond = { crushed=55591, uncut=55665, flawed=55664, enchanted=55741, radiant=55742, perfect=55745, polished=55668 },
    emerald = { crushed=55593, uncut=55663, flawed=55660, enchanted=55737, radiant=55740, perfect=55747, polished=55670 },
    garnet = { crushed=55578, dust=55570, uncut=55612, flawed=55634, shard=55586, enchanted=55733, radiant=55711, perfect=55689, polished=55656 },
    hematite = { uncut=55594, flawed=55616, perfect=55671, radiant=55693, enchanted=55715, polished=55638 },
    jade = { uncut=55608, flawed=55630, shard=55610, enchanted=55729, radiant=55707, perfect=55685, polished=55652 },
    labradorite = { uncut=55611, flawed=55633, perfect=55688, radiant=55710, enchanted=55732, polished=55655 },
    lapis = { uncut=55600, flawed=55622, enchanted=55721, radiant=55699, perfect=55677, polished=55644 },
    malachite = { dust=55568, crushed=55576, shard=55584, uncut=55603, flawed=55625, perfect=55680, radiant=55702, enchanted=55724, polished=55647 },
    moonstone = { uncut=55596, flawed=55618, perfect=55673, radiant=55695, enchanted=55717, polished=55640 },
    onyx = { uncut=55609, flawed=55631, perfect=55686, radiant=55708, enchanted=55730, polished=55653 },
    opal = { uncut=55610, flawed=55632, enchanted=55731, radiant=55709, perfect=55687, polished=55654 },
    pearl = { uncut=55607, flawed=55629, enchanted=55728, radiant=55706, perfect=55684, polished=55651 },
    peridot = { uncut=55615, crushed=55581, dust=55573, shard=55589, flawed=55637, perfect=55692, radiant=55714, enchanted=55736, polished=55659 },
    ruby = { crushed=55590, uncut=55662, flawed=55661, enchanted=55738, radiant=55739, perfect=55744, polished=55667 },
    sapphire = { crushed=55592, uncut=55666, flawed=55689, radiant=55743, perfect=55746, polished=55669 },
    topaz = { uncut=55605, flawed=55627, enchanted=55726, radiant=55704, perfect=55682, polished=55649 },
    tourmaline = { crushed=55580, dust=55572, uncut=55614, flawed=55636, shard=55588, enchanted=55735, radiant=55713, perfect=55691, polished=55658 },
    turquoise = { uncut=55597, flawed=55619, enchanted=55718, radiant=55696, perfect=55674, polished=55641 },
}

-- Pick the gemstone keyword matched in the speech. Earlier multi-word
-- patterns like "lapis lazuli" / "moonstone" are normalized below.
local stone
if string.find(s, "lapis") or string.find(s, "lazuli") then stone = "lapis"
elseif string.find(s, "moonstone") or string.find(s, "moon") then stone = "moonstone"
elseif string.find(s, "bloodstone") or string.find(s, "blood") then stone = "bloodstone"
else
    for k, _ in pairs(gem_table) do
        if string.find(s, k) then stone = k; break end
    end
end

-- Special cases the exchange refuses outright.
if string.find(s, "jasper") then
    actor:send(tostring(self.name) .. " says, 'I'm sorry, we don't stock jasper.'")
    self:command("half")
    return true
end
if stone == "malachite" and string.find(s, "chunk") then
    actor:send(tostring(self.name) .. " says, 'That is not an item we trade in the gem exchange.'")
    self:command("half")
    return true
end

if not stone then
    return true
end

local g = grade()
local gem_id = gem_table[stone] and gem_table[stone][g]
if not gem_id then
    actor:send(tostring(self.name) .. " says, 'I'm sorry, we don't stock that grade of " .. stone .. ".'")
    return true
end

local gem_name = tostring(objects.template(math.floor(gem_id / 100), gem_id % 100).name)
actor:send(tostring(self.name) .. " asks you, 'You want " .. gem_name .. "?'")
actor:set_quest_var("gem_exchange", "gem_id", gem_id)
return true$trig$, '34390266c152f0b98b84ef8450399ac3'),
  -- data/triggers/085/085_01_quest_preamble_ziijhan.lua
  (85, 1, $trig$-- Converted from DG Script #8501: quest_preamble_ziijhan
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: destiny destiny? destinies destinies? I know
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "destiny") or string.find(speech_lower, "destinies") or string.find(speech_lower, "i know")) then
    return true  -- No matching keywords
end
if actor:get_quest_stage("nec_dia_ant_subclass") > 0 then
    return true
end

local classquest = false
if string.find(actor.class, "warrior") then
    if actor.level >= 10 and actor.level <= 25 then
        if actor.race == "elf" or actor.race == "faerie_seelie" then
            actor:send("<red>Your race may not subclass to anti-paladin.</>")
            return true
        end
        classquest = true
    end
elseif string.find(actor.class, "cleric") then
    if actor.level >= 10 and actor.level <= 35 then
        if actor.race == "elf" or actor.race == "faerie_unseelie" then
            actor:send("<red>Your race may not subclass to diabolist.</>")
            return true
        end
        classquest = true
    end
elseif string.find(actor.class, "sorcerer") then
    if actor.level >= 10 and actor.level <= 45 then
        if actor.race == "elf" or actor.race == "faerie_seelie" then
            actor:send("<red>Your race may not subclass to necromancer.</>")
            return true
        end
        classquest = true
    end
else
    actor:send(tostring(self.name) .. " says, 'Sorry, I cannot help you achieve your destiny.'")
    return true
end

if not classquest then
    return true
end

wait(2)
if globals.use_subclass then
    actor:send(tostring(self.name) .. " says, 'Sorry little one.  I am already setting up one quest - come back in a moment.'")
    return true
end
if actor.alignment >= -349 then
    actor:send(tostring(self.name) .. " says, 'Begone, fool.  You are far too righteous to join our brotherhood.'")
    return true
end

self:command("nod " .. tostring(actor.name))
local subclass = nil
if string.find(actor.class, "warrior") then
    if actor.level >= 10 and actor.level <= 25 then
        actor:send(tostring(self.name) .. " says, 'Do ye wish to join the ranks of the unholy warriors?'")
        subclass = "Ant"
    elseif actor.level < 10 then
        actor:send(tostring(self.name) .. " says, 'Strong thirst for slaughter for one so young.  Come back once you've gained some more experience.'")
    else
        actor:send(tostring(self.name) .. " says, 'You are already following your destiny.  I cannot help you any further.'")
    end
elseif string.find(actor.class, "cleric") then
    if actor.level >= 10 and actor.level <= 35 then
        actor:send(tostring(self.name) .. " says, 'Do ye wish to join the ranks of the diabolists and derive power from madness and darkness?'")
        subclass = "Dia"
    elseif actor.level < 10 then
        actor:send(tostring(self.name) .. " says, 'Strong thirst for madness for one so young.  Come back once you've gained some more experience.'")
    else
        actor:send(tostring(self.name) .. " says, 'You are already following your destiny.  I cannot help you any further.'")
    end
elseif string.find(actor.class, "sorcerer") then
    if actor.level >= 10 and actor.level <= 45 then
        actor:send(tostring(self.name) .. " says, 'Do ye wish to join the ranks of the necromancers and have power over death?'")
        subclass = "Nec"
    elseif actor.level < 10 then
        actor:send(tostring(self.name) .. " says, 'Strong thirst for death for one so young.  Come back once you've gained some more experience.'")
    else
        actor:send(tostring(self.name) .. " says, 'You are already following your destiny.  I cannot help you any further.'")
    end
end
if subclass then
    globals.use_subclass = subclass
end
return true$trig$, '6cac0782bb4d86329080e670d8e7319d'),
  -- data/triggers/103/103_09_khysan-greet.lua
  (103, 9, $trig$local ice_stage = actor:get_quest_stage("ice_shards")
local wand_stage = actor:get_quest_stage("type_wand")

local seen_before = false
if (ice_stage or 0) > 0 and ice_stage > 0 then
    seen_before = true
end
if wandstep and wand_stage > wandstep then
    seen_before = true
end
if wandstep and wand_stage == wandstep and actor:get_quest_var("type_wand:greet") == 1 then
    seen_before = true
end

wait(1)
actor:send(self.name .. " looks up at your approach.")

if seen_before then
    self:say("Welcome back my friend.")
    wait(2)
    if (ice_stage or 0) > 0 and ice_stage > 0 and not actor:get_has_completed("ice_shards") then
        self:say("Did you find any more clues?")
        if wandstep and wand_stage == wandstep then
            local minlevel = (wandstep - 1) * 10
            wait(1)
            if actor.level >= minlevel then
                if actor:get_quest_var("type_wand:greet") == 0 then
                    self:say("Or is there something else that brings you back?")
                else
                    self:say("Or do you have what I need for a new staff?")
                end
            end
        end
    else
        if wandstep and wand_stage == wandstep then
            local minlevel = (wandstep - 1) * 10
            if actor.level >= minlevel then
                if actor:get_quest_var("type_wand:greet") == 0 then
                    self:say("Is there something else that brings you back?")
                else
                    self:say("Do you have what I need for a new staff?")
                end
            end
        end
    end
else
    self.room:send(self.name .. " smiles warmly and says, 'Welcome to Phoenix Feather Resort.'")
    wait(1)
    self:say("We are currently offering free services to all adventurers.")
    wait(1)
    self:command("bow " .. actor.name)
    self:say("Please enjoy your stay.  You may enter the hot springs to the south.")
    if wandstep and wand_stage == wandstep then
        wait(1)
        local minlevel = (wandstep - 1) * 10
        if actor.level >= minlevel and actor:get_quest_var("type_wand:greet") == 0 then
            self.room:send(self.name .. " says, 'I see you're crafting something.  If you want my help, we can talk about <b:cyan>[upgrades]</>.'")
        end
    end
    if not ((ice_stage or 0) > 0 and ice_stage > 0) then
        wait(3)
        if string.find(actor.class, "cryomancer") then
            if actor:get_has_completed("major_globe_spell")
               and actor:get_has_completed("relocate_spell_quest")
               and actor:get_has_completed("wall_ice")
               and actor:get_has_completed("waterform")
               and actor:get_has_completed("flood") then
                self:say("Oh, " .. actor.name .. " " .. tostring(actor.title) .. "!  I've heard of you!  You're quite talked about amongst our fellow cryomancers.")
                if actor.level > 88 then
                    self.room:send("</>")
                    self:say("Makes me wonder if you could have mastered the most powerful cryomantic spell ever known.")
                end
            end
        end
    end
end$trig$, '742104ef7d213ad91d758727d89d4bd7'),
  -- data/triggers/123/123_00_megalith_quest_priestess_greet.lua
  (123, 0, $trig$-- Converted from DG Script #12300: megalith_quest_priestess_greet
-- Original: MOB trigger, flags: GREET, probability: 100%
-- This trigger is different depending on stage and where in the stage the questor is at
-- 
local item1 = (actor:get_quest_var("megalith_quest:item1") == 1)
local item2 = (actor:get_quest_var("megalith_quest:item2") == 1)
local item3 = (actor:get_quest_var("megalith_quest:item3") == 1)
local item4 = (actor:get_quest_var("megalith_quest:item4") == 1)
if (actor.is_player) and (actor:get_quest_stage("megalith_quest") < 1) and (actor.level < 100) then
    wait(2)
    self.room:send(tostring(self.name) .. " looks up, startled to see new faces.")
    self:say("Goddess be praised!")
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'We were attacked by the Unseelie Court and their monstrosities on our journey here through the forest.  I am deeply in need of <b:cyan>assistance</>!'")
    -- 
    -- Check in during stage 1, seeing if the questor has her tools or not
    -- 
elseif actor:get_quest_stage("megalith_quest") == 1 then
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'Have you been able to find replacements for the sacred prophetic implements?  Do you need a reminder of your <b:cyan>[progress]?</>'")
    -- 
    -- If all the Keepers have been helped in stage 2, give the incantation to start stage 3
    -- 
elseif (actor:get_quest_stage("megalith_quest") == 2) and (actor:get_quest_var("megalith_quest:item1") == 1) and (actor:get_quest_var("megalith_quest:item2") == 1) and (actor:get_quest_var("megalith_quest:item3") == 1) and (actor:get_quest_var("megalith_quest:item4") == 1) then
    wait(2)
    self:say("We're ready to finish calling the elements!  If you wish to proceed, repeat after me:")
    self.room:send("</>")
    self.room:send("<b:cyan>Under the watchful eye of Earth, Air, Fire, and Water, we awaken this hallowed ground!</>")
    -- 
    -- If all the Keepers have not been helped in stage 2, do a check in
    -- 
elseif actor:get_quest_stage("megalith_quest") == 2 then
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'I hope your work with the Keepers is coming along well.  Do you need a reminder of your <b:cyan>[progress]?</>'")
    -- 
    -- If all the reliquaries have been returned and stage 4 is ready to start, ask if ready to proceed
    -- 
elseif (actor:get_quest_stage("megalith_quest") == 4) and ((actor:get_quest_var("megalith_quest:reliquary") or 0) ~= 0) then
    wait(2)
    self:say("It's time.  Are you ready to proceed?")
    -- 
    -- If all the reliquaries have not been returned yet in stage 3, do a check in
    -- 
elseif actor:get_quest_stage("megalith_quest") == 3 then
    wait(2)
    self:say("I hope you have had luck finding the reliquaries.")
    -- 
    -- If the quest was successfully completed, give a friendly welcome.
    -- 
elseif actor:get_has_completed("megalith_quest") then
    wait(2)
    if actor.gender == "female" then
        self:say("Hail and well met, Sister!")
    elseif actor.gender == "male" then
        self:say("Hail and well met, Brother!")
    else
        self:say("Hail and well met!")
    end
    -- 
    -- If the quest was failed,
    -- 
elseif actor:get_has_failed("megalith_quest") then
    wait(2)
    self:say("Welcome back.")
    wait(2)
    self:say("Had that we reunited under better blessings...")
    wait(3)
    self:say("Though perhaps we could try again?")
end$trig$, '0f3e6c34782ad2884111dfe71cb90365'),
  -- data/triggers/123/123_05_megalith_quest_priestess_speech_start.lua
  (123, 5, $trig$-- Converted from DG Script #12305: megalith_quest_priestess_speech_start
-- Original: MOB trigger, flags: SPEECH, SPEECH_TO, num_arg: 1 (DG word-list mode, not a probability)

-- DG word list (num_arg 1): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "yes?"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
-- This trigger serves as both the starting, restarting, and advancing from stage 3 to stage 4 trigger
-- If starting for the first time
-- 
if actor:get_quest_stage("megalith_quest") < 1 then
    actor:start_quest("megalith_quest")
    wait(2)
    self:say("May the Goddess smile upon you!")
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'First, I'll need your help replacing the <b:cyan>implements</> destroyed in the maze getting here.'")
    -- 
    -- If restarting
    -- 
elseif actor:get_has_failed("megalith_quest") then
    actor:restart_quest("megalith_quest")
    self.room:send("</>")
    self:command("smile")
    self:say("Then let us give it another go!")
    -- (empty room echo)
    self.room:send(tostring(self.name) .. " says, 'Some of our <b:cyan>implements</> were destroyed in our previous attempt.'")
end
-- 
-- List tools for stage 1
-- 
if actor:get_quest_stage("megalith_quest") == 1 then
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'We need the following:")
    self.room:send("- <b:white>Salt</>.")
    -- (empty room echo)
    self.room:send("- A <b:cyan>goblet or chalice</> to hold water.")
    self.room:send("</>    My home island in the Green Green Sea has several goblets, though do be")
    self.room:send("</>    careful which one you pick.  Some of them tend to be poisoned.")
    -- (empty room echo)
    self.room:send("</>    I understand there is a beautiful chalice recently lost from the Abbey of")
    self.room:send("</>    St. George that might work as well.")
    -- (empty room echo)
    self.room:send("- Some kind of <yellow>censer</> to burn incense in.")
    self.room:send("</>    There are a few other more nefarious religions which use incense burners in")
    self.room:send("</>    their rituals.  You may be able to steal one from them.")
    -- (empty room echo)
    self.room:send("- A <b:red>candle</>.")
    self.room:send("</>    Candles are common to light the dark in the far north, and in some")
    self.room:send("</>    underground communities.'")
    wait(6)
    self:say("Bring these to me to begin the Great Rite!")
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'If you want to know more about what my Sisters and I are doing, you can ask any of us <b:cyan>who are you?</>'")
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'If you need a reminder of your <b:cyan>[progress]</>, you may ask me at any time.'")
    self:command("bow " .. tostring(actor.name))
    -- 
    -- If ready to continue stage 4
    -- 
elseif actor:get_quest_stage("megalith_quest") > 0 and self.room.zone_id == 123 and self.room.local_id == 89 and actor:get_quest_var("megalith_quest:reliquary") == 1 then
    wait(2)
    self:say("The Great Rite of Invocation has a great deal of call and response.  I will chant a line and you must repeat it to continue the ritual.  The coven will chant their response after you do.")
    wait(4)
    self:say("Repeat after me.")
    wait(2)
    self:emote("raises her arms to the sky.")
    self.room:send(tostring(self.name) .. " chants, '<b:cyan>Great Lady of the Stars, hear our prayer!</>'")
    actor:set_quest_var("megalith_quest", "prayer", 1)
end$trig$, '5f73bfc163df7447c7a2d1e9deedc6af'),
  -- data/triggers/123/123_06_megalith_quest_priestess_receive.lua
  (123, 6, $trig$-- Converted from DG Script #12306: megalith_quest_priestess_receive
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
local _return_value = true  -- Default: allow action
-- This trigger serves as the basis for the returning of items to the high priestess and advancing stages 1 and 3.
-- It is heavily copied from the Hot Springs quests.
-- Several of the stages have multiple items the questor could return.
-- Some can result in the quest variables [bad1-3] being placed on the character.
-- Ideally, there will be 0 [bad]
-- If there are 2 [bad] or more at the end, the final step of the quest will fail.
