        return true
    else
        actor:send(tostring(self.name) .. " says, 'You are already following your destiny.  I cannot help you any further.'")
        return true
    end
end

wait(2)

if not classquest then
    return true
end

if string.find(s, "yes") then
    if actor.alignment > 349 and actor:get_quest_stage("pri_pal_subclass") == 0 then
        if not globals.use_subclass then
            actor:send(tostring(self.name) .. " says, 'First, we must discuss your destiny.'")
        else
            actor:start_quest("pri_pal_subclass", globals.use_subclass)
            self:command("smile " .. tostring(actor.name))
            actor:send(tostring(self.name) .. " says, 'You may check your <b:cyan>[subclass progress]</> or ask me to <b:cyan>[repeat]</> myself at any time.'")
            wait(1)
            actor:send(tostring(self.name) .. " says, 'It is necessary to make a quest such as this quite tough to ensure ensure you really want to do this.'")
            wait(2)
            actor:send(tostring(self.name) .. " says, 'I am sure you will complete the <b:cyan>quest</> though.'")
        end
    else
        actor:send(tostring(self.name) .. " says, 'I cannot help you if you are not good little one.'")
    end
else
    self:command("sigh")
    actor:send(tostring(self.name) .. " says, 'It is a shame we have so few willing to join us these days, but I cannot compel you.  Farewell, and I hope you come to reconsider your decision sometime.'")
    wait(2)
    actor:send("Silania makes a gesture with her hand and you are blinded for a second.")
    self.room:send_except(actor, "Silania makes a gesture with her hand and " .. tostring(actor.name) .. " disappears.")
    actor:teleport(get_room(185, 66))
end

globals.use_subclass = nil$trig$, 'e42634f5fdb99d15c70df7a6cb952c3d'),
  -- data/triggers/324/324_08_kerriston_north_horse_timer.lua
  (324, 8, $trig$-- Converted from DG Script #32408: Kerriston_north_horse_timer
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
-- This is the reception of the carrot
-- that kicks off the whole affair.
-- Legacy mteleport to a room that is not there is a no-op, and zone 324 has no rooms at 324:97,
-- 324:98 or 324:65 (legacy 32597, 32598, 32565 are not in 324.wld either), so the hops through
-- them are skipped instead of raising an error halfway through the ride.
local function ride_to(zone, id)
    local room = get_room(zone, id)
    if room then
        actor:teleport(room)
        self:teleport(room)
    end
    return room
end
if actor.is_player then
    if object.zone_id == 324 and object.local_id == 21 then
        wait(1)
        ride_to(324, 197)
        self:destroy_item("carrot")
        -- Label reference: do_it_to_it
        wait(5)
        self.room:send("The world spins by you as you struggle to hang on!")
        wait(5)
        self.room:send("The sound of thundering hooves is almost deafening!")
        wait(5)
        self.room:send("You slip and nearly fall off!")
        wait(5)
        self.room:send("The horse bucks wildly almost throwing you!")
        wait(5)
        self.room:send("The tall grass whips by your feet so quickly it stings!")
        wait(5)
        self.room:send("Are you slowing down?")
        wait(2)
        ride_to(324, 61)
        wait(1)
        actor:command("look")
        self:command("pant")
        self.room:send("The trained <yellow>horse</> wiggles from underneath you.")
        wait(1)
        self.room:send("The trained <yellow>horse</> is summoned by his master.")  -- from MPROG
        self.room:send("The trained <yellow>horse</> disappears in a puff of smoke.")  -- from MPROG
    else
        wait(1)
        self:command("eye " .. tostring(actor.name))
        wait(3)
        self:command("bite " .. tostring(actor.name))
        self:command("smile me")
    end
end
-- Legacy `purge_me`: the horse is gone once the ride (or the refusal) is over.
world.destroy(self)$trig$, '5281dcc7083755eab0bab6eb969b1d11'),
  -- data/triggers/324/324_13_kerristone_north_trainer_bribemg.lua
  (324, 13, $trig$-- Converted from DG Script #32413: Kerristone_north_trainer_bribeMG
-- Original: MOB trigger, flags: BRIBE, num_arg: 42 (minimum bribe in copper)

-- DG BRIBE num_arg 42: fires only when the coins are worth at least 42 copper.
if (value or 0) < 42 then
    return true
end
-- This is one of the bribe progs that will
-- let players buy a horse to bolt to Mugnork
-- The horse trigs have been altered in concept
-- on how they deliver the players to the destination
-- but there's no reason why this trig can't exist
-- as is to kick it off
if actor.is_player then
    -- The ride ends in 324:165 (legacy 32565), a room the legacy world never defined. Without it the
    -- ride cannot arrive, so hand the money back instead of selling a trip to nowhere.
    if not get_room(324, 165) then
        wait(1)
        self.room:send(tostring(self.name) .. " says, 'I am sorry, the road to Mugnork is closed right now.'")
        self:command("give " .. tostring(value) .. " copper " .. tostring(actor.name))
        return true
    end
    wait(1)
    self.room:send(tostring(self.name) .. " says, '</>Ahh Thankyou! You will not be disappointed.</>'")
    self.room:send(tostring(self.name) .. " says, '</>I have one of the fastest </><blue>&9stallions</> in the land for you!'")
    wait(2)
    self.room:send("</>A <yellow>horse</> trainer leads a fine looking <blue>&9stallion</> into the room.")
    self.room:spawn_mobile(324, 23)
    wait(2)
    self.room:send("</>A horse trainer gets under you and pushes you up into the saddle.</>")
    -- mload obj: the strawberry goes into the trainer's inventory so the give below can hand it over
    self:spawn_object(324, 25)
    self.room:send(tostring(self.name) .. " says, 'Feed him this <red>strawberry</> and he will know that you want to go to <b:cyan>Mugnork</>.'")
    self:command("give strawberry " .. tostring(actor.name))
    wait(2)
    self.room:send("</>A <yellow>horse</> trainer forces your hand towards the mouth of the horse.")
    actor:command("give strawberry stallion")
    self.room:send(tostring(self.name) .. " says, 'Good journey!'")
end$trig$, 'db054e139a4be261c2570312f958233f'),
