  -- data/triggers/390/390_16_flood_lady_heart_replacement.lua
  (390, 16, $trig$if string.lower(speech) ~= "i lost the heart" then
    return true
end
if actor:get_quest_stage("flood") == 0 then
    return true
end

wait(2)
self:command("scream")
wait(2)
self.room:send(self.name .. " shrieks, 'HOW DARE YOU!!!'")
wait(1)
local dealt = actor:damage(400)  -- physical drowning
actor:send(self.name .. " fills your lungs with water! (<b:blue>" .. tostring(dealt) .. "</>)")
self.room:send_except(actor, self.name .. " fills " .. actor.name .. "'s lungs with water! (<b:blue>" .. tostring(dealt) .. "</>)")
wait(2)
self:emote("holds her hands in front of her.")
wait(1)
self.room:send("Water flows up " .. self.name .. "'s body and swirls around her arms.")
wait(1)
self.room:send("The water coalesces into a shimmering jewel in the Lady's outstretched hands.")
wait(1)
self.room:spawn_object(390, 0)
self:command("give heart " .. actor.name)
self:say("Do not make this mistake again, Envoy.")$trig$, 'af5c46a4eefbc1702602bdeaaf6915fb'),
  -- data/triggers/430/430_53_word_command_dargo_speech1.lua
  (430, 53, $trig$-- Converted from DG Script #43053: word_command_dargo_speech1
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: yes yes? sure okay yeah
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "yes") or string.find(string.lower(speech), "yes?") or string.find(string.lower(speech), "sure") or string.find(string.lower(speech), "okay") or string.find(string.lower(speech), "yeah")) then
    return true  -- No matching keywords
end
wait(2)
if globals.questor == actor.name then
    self:say("Lead on!")
elseif actor:get_has_completed("word_command") then
    self:emote("stars in wide-eyed terror.")
    wait(2)
    self:say("Don't I know you already?!  Cyprianum is tormenting me again!!")
    wait(1)
    self.room:send(tostring(self.name) .. " screams, 'NOOOOOOOO!!!!!' as he runs wildly into the shadows!")
    world.destroy(self)
elseif (string.find(actor.class, "priest") or string.find(actor.class, "diabolist")) and actor.level > 72 then
    self:say("Thank you!")
    if actor:get_quest_stage("word_command") == 0 then
        actor:start_quest("word_command")
    end
    globals.questor = actor.name
    self:follow(actor)
else
    self.room:send(tostring(self.name) .. " says, 'I don't know if you can protect me from the demonic forces")
    self.room:send("</>here...  You'll need in-depth knowledge of demons to get us out of")
    self.room:send("</>here alive!'")
end$trig$, 'a69fca7a05e6767da886be9074c01e21'),
  -- data/triggers/430/430_57_word_of_command_dargo_order.lua
  (430, 57, $trig$-- Converted from DG Script #43057: word_of_command_dargo_order
-- Original: MOB trigger, flags: COMMAND, probability: 100%

-- Command filter: order
if not (cmd == "order") then
    return true  -- Not our command
end
local _return_value = false  -- Default: block the command (legacy script_driver ret_val = 1)
if string.find(arg, "enter door") then
    if actor:get_quest_stage("word_command") == 3 then
        if self.room.zone_id == 430 and self.room.local_id == 176 then
            self:command("enter door")
        else
            self.room:send(tostring(self.name) .. " looks frantically for a door and panics!")
        end
    elseif actor:get_quest_stage("word_command") > 0 then
        self:say("I'm not free from the curse yet!")
    end
end
return _return_value$trig$, '5fbde3a255a0ce48557d0c2b36fba9ab'),
  -- data/triggers/462/462_04_nukreth_spire_chieftain_death.lua
  (462, 4, $trig$-- Converted from DG Script #46204: Nukreth Spire chieftain death
-- Original: MOB trigger, flags: DEATH, probability: 100%
-- TODO(parity): legacy DG had a "pathrnd" reroll loop that never updated the
-- quest var (would loop forever). We just roll once. Group iteration also
-- skipped non-present members by incrementing `i`; in Lua we just continue.
local rnd = random(1, 4)
if actor and actor.is_player then
    local i = actor.group_size
    if i then
        local a = 1
        while i >= a do
            local person = actor.group_member[a]
            if person and person.room == self.room then
                if person:get_quest_stage("nukreth_spire") == 0 then
                    person:start_quest("nukreth_spire")
                end
            end
            a = a + 1
        end
    elseif actor:get_quest_stage("nukreth_spire") == 0 then
        actor:start_quest("nukreth_spire")
    end
end
if rnd == 1 then
    run_room_trigger(462, 0)
elseif rnd == 2 then
    run_room_trigger(462, 1)
elseif rnd == 3 then
    run_room_trigger(462, 2)
elseif rnd == 4 then
    run_room_trigger(462, 3)
end$trig$, '9a1c788ed2c2f8fd768ef1aedd77cb1e'),
  -- data/triggers/462/462_05_nukreth_spire_path2_3_4_captive_greet.lua
  (462, 5, $trig$-- Converted from DG Script #46205: Nukreth Spire path2 3 4 captive greet
-- Original: MOB trigger, flags: GREET, probability: 100%
wait(2)
local kill, job, follow
local task = globals.task
local in_breaker_room = self.room.zone_id == 462 and self.room.local_id == 78
local in_tracker_rooms = self.room.zone_id == 462
    and (self.room.local_id == 65 or self.room.local_id == 20 or self.room.local_id == 5)
if actor:get_quest_stage("nukreth_spire") > 0 then
    if not actor:get_quest_var("nukreth_spire:pathnumber") then
        if in_breaker_room then
            -- the spiritbreaker is still alive
            if world.count_mobiles(462, 24) > 0 then
                kill = 1
            else
                -- the spiritbreaker is not alive, but they need to find something first
                if not task then
                    job = 1
                else
                    -- the spiritbreaker is not alive, and they have found the thing they need
                    follow = 1
                end
            end
        elseif in_tracker_rooms then
            if world.count_mobiles(462, 1) > 0 then
                -- the gnoll trackers are alive
                kill = 2
            else
                if not task then
                    -- the trackers are dead, but they need to find something first
                    job = 1
                else
                    -- the trackers are dead, and they have found the thing they need
                    follow = 1
                end
            end
        end
    end
end
if kill == 1 then
    if self.local_id == 20 then
        self:say("Help me kill this thing!")
    elseif self.local_id == 21 then
        self:say("Save me from this monster!!")
    elseif self.local_id == 22 then
        self:say("WE TAKE REVENGE!!!")
    elseif self.local_id == 23 then
        self:say("Get this beast off me!!")
    end
elseif kill == 2 then
    if self.local_id == 20 then
        self:say("Help me kill these things!")
    elseif self.local_id == 21 then
        self:say("Save me from these monsters!!")
    elseif self.local_id == 22 then
        self:say("WE TAKE REVENGE!!!")
    elseif self.local_id == 23 then
        self:say("Get these beasts off me!!")
    end
elseif job == 1 then
    self:say("Wait, I can't leave yet!")
    -- (empty room echo)
    if self.local_id == 20 then
        self:say("Please, help me find my husband.")
    elseif self.local_id == 21 then
        self:say("Please, help me save my baby!")
    elseif self.local_id == 22 then
        self:say("Bring me my axe!")
    elseif self.local_id == 23 then
        self:say("Help me find my treasure!")
    end
elseif follow == 1 then
    self:say("Say 'follow me' and I'll follow you out!")
end$trig$, '5727a80132ab8cd6d07f35000bec0748'),
