  -- data/triggers/462/462_35_nukreth_spire_path1_captive_greet.lua
  (462, 35, $trig$-- Converted from DG Script #46235: Nukreth Spire path1 captive greet
-- Original: MOB trigger, flags: GREET_ALL, probability: 100%
if actor.zone_id == 462 and actor.local_id == 25 and globals.task ~= "done" then
    globals.task = "done"
    wait(2)
    self.room:send(tostring(self.name) .. " rushes to her husband.")
    self.room:send("Choking back tears she says, 'I can't believe it!'")
    wait(1)
    self:say("How can I ever thank you?")
    self.room:send("She wraps her arms around her husband in a tight embrace.")
    wait(1)
    self:say("Now, who's leading us out of this hellhole?")
    return true
elseif actor.is_player then
    local kill, job, follow
    local task = globals.task
    local in_breaker_room = self.room.zone_id == 462 and self.room.local_id == 78
    local in_tracker_rooms = self.room.zone_id == 462
        and (self.room.local_id == 65 or self.room.local_id == 20 or self.room.local_id == 5)
    if actor:get_quest_stage("nukreth_spire") > 0 then
        if not actor:get_quest_var("nukreth_spire:pathnumber") then
            if in_breaker_room then
                -- the spiritbreaker is still alive
                if world.count_mobiles(462, 24) > 0 then
                    kill = 1
                else
                    -- the spiritbreaker is not alive, but they need to find something first
                    if not task then
                        job = 1
                    else
                        -- the spiritbreaker is not alive, and they have found the thing they need
                        follow = 1
                    end
                end
            elseif in_tracker_rooms then
                if world.count_mobiles(462, 1) > 0 then
                    -- the gnoll trackers are alive
                    kill = 2
                else
                    if not task then
                        -- the trackers are dead, but they need to find something first
                        job = 1
                    else
                        -- the trackers are dead, and they have found the thing they need
                        follow = 1
                    end
                end
            end
        end
    end
    if kill == 1 then
        actor:send(tostring(self.name) .. " says, 'Help me kill this thing!'")
    elseif kill == 2 then
        actor:send(tostring(self.name) .. " says, 'Help me kill these things!'")
    elseif job == 1 then
        actor:send(tostring(self.name) .. " says, 'Wait, I can't leave yet!'")
        -- (empty room echo)
        actor:send(tostring(self.name) .. " says, 'Please, help me find my husband.'")
    elseif follow == 1 then
        actor:send(tostring(self.name) .. " says, 'Say 'follow me' and I'll follow you out!'")
    end
end$trig$, 'e01b970e837755b6f55ea2c89b2d4507'),
  -- data/triggers/481/481_153_mccabe_greet.lua
  (481, 153, $trig$-- Converted from DG Script #48253: mccabe greet
-- Original: MOB trigger, flags: GREET, probability: 100%
local stage = actor:get_quest_stage("meteorswarm")
wait(1)
-- No one should be here but sorcs and pyros, so let's throw the rest back out
if actor.class ~= "sorcerer" and actor.class ~= "pyromancer" and actor:get_quest_stage("type_wand") < (wandstep or 999) then
    self:command("con " .. tostring(actor))
    wait(2)
    self:say("What are you doing here?! Get out!")
    wait(1)
    self.room:send_except(actor, "<b:blue>" .. tostring(self.name) .. " </><cyan> sends a blast of air at &9<blue>" .. tostring(actor.name) .. "<cyan> sending them<blue> tumbling!</>")
    actor:send("<b:blue>" .. tostring(self.name) .. " </><cyan> sends a blast of air at <b:red>YOU<cyan> sending you<blue> tumbling!</>")
    actor:teleport(get_room(481, 154))
    actor:send("<b:blue>" .. tostring(self.name) .. "'s </><cyan>blast of air sends you<blue> tumbling!</>")
    actor:teleport(get_room(481, 153))
    actor:send("<b:blue>" .. tostring(self.name) .. "'s </><cyan>blast of air sends you<blue> tumbling!</>")
    actor:teleport(get_room(481, 152))
    actor:send("<b:blue>" .. tostring(self.name) .. "'s </><cyan>blast of air comes at you from a new angle, sending you<blue> tumbling!</>")
    actor:teleport(get_room(481, 151))
    local damage = (actor.level * 2) + random(1, 30)
    local damage_dealt = actor:damage(damage)  -- type: fire
    actor:send("<b:red>You sustain </><red>severe burns<blue> as you plunge head first through drizzling </><red>lava.</> (<b:red>" .. tostring(damage_dealt) .. "</>)")
elseif (string.find(actor.class, "sorcerer") and actor.level > 72) or (string.find(actor.class, "pyromancer") and actor.level > 80) or actor:get_quest_stage("type_wand") == "wandstep" then
    local minlevel = ((wandstep or 1) - 1) * 10
    if (string.find(actor.class, "sorcerer") and actor.level > 72) or (string.find(actor.class, "pyromancer") and actor.level > 80) then
        if actor:get_quest_var("meteorswarm:new") ~= "no" then
            actor:send(tostring(self.name) .. " tells you, 'Do you have the new meteorite?'")
        elseif (stage or 0) == 0 then
            self.room:spawn_mobile(481, 151)
            self:command("peer seagull")
            self:emote("focuses closely on the seagull flying overhead.")
            self.room:send(tostring(self.name) .. " starts casting '<b:yellow>meteorswarm</>' at an unsuspecting seagull.")
            wait(1)
            run_room_trigger(481, 157)
            self.room:find_actor("seagull"):command("panic")
            self.room:find_actor("seagull"):emote("panics and flees to the north.")
            world.destroy(self.room:find_actor("seagull"))
            wait(2)
            self:command("giggle")
            wait(5)
            actor:send(tostring(self.name) .. " tells you, 'I see you admire my conjuring.  Perhaps you've never seen anyone calling <b:cyan>meteors</>?'")
        elseif stage == 1 then
            actor:send(tostring(self.name) .. " tells you, 'Have you spoken to Jemnon?  He's in some tavern, no doubt, waiting for some new blunder to embark on.'")
        elseif stage == 2 then
            actor:send(tostring(self.name) .. " tells you, 'Well, did Jemnon tell you where the rock demon is?'")
        elseif stage == 3 then
            actor:send(tostring(self.name) .. " tells you, 'Have you found a suitable focus?'")
        elseif stage == 4 then
            actor:send(tostring(self.name) .. " tells you, 'I can see from the singe marks you accomplished your task!  Are you ready to press on?'")
        elseif stage == 5 then
            actor:send(tostring(self.name) .. " tells you, 'Were you able to glean something from Dargentan's teachings?'")
        end
        if actor:get_quest_stage("type_wand") == "wandstep" then
            if actor.level >= minlevel then
                if actor:get_quest_var("type_wand:greet") == 0 then
                    actor:send(tostring(self.name) .. " tells you, 'Or is there even MORE you want from me?  You seem to be in need of a crafting <b:cyan>[upgrade]</>.'")
                else
                    actor:send(tostring(self.name) .. " says, 'Do you have what I need for the " .. tostring(weapon) .. "?'")
                end
            end
        end
    else
        if actor.level >= minlevel then
            if actor:get_quest_var("type_wand:greet") == 0 then
                actor:send(tostring(self.name) .. " tells you, 'I see you're crafting something.  If you want my help, we can talk about <b:cyan>[upgrades]</>.'")
            else
                actor:send(tostring(self.name) .. " tells you, 'Do you have what I need for the " .. tostring(weapon) .. "?'")
            end
        end
    end
end$trig$, '051cf8a533163a846febd9cfb8cc616d'),
  -- data/triggers/481/481_156_mccabe_dialog.lua
  (481, 156, $trig$-- Converted from DG Script #48256: mccabe dialog
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: meteor meteors meteors? meteorswarm yes no
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "meteor") or string.find(string.lower(speech), "meteors") or string.find(string.lower(speech), "meteors?") or string.find(string.lower(speech), "meteorswarm") or string.find(string.lower(speech), "yes") or string.find(string.lower(speech), "no")) then
    return true  -- No matching keywords
end
-- **McCabes Speech Trigger***
-- This trigger represents the launching point, ending point, and intersection of the 3 parts of the meteor quest.
-- stage 1 deals with finding Jemnon
-- stage 2 is getting a mastery of earth, and ends back here.
-- stage 3 sends the quester off to the fire temple high priest, and ends back here.
-- stage 4 sends the quester to dargentans lair to master air, which then ends back here.
-- stage 5 means the player has mastered all 3 elements, combined them into an item, and can now cast a meteorswarm with that item.
-- the quest is actually completed by the item itself, when the player casts its one and only charge of meteorswarm.
local stage = actor:get_quest_stage("meteorswarm")
wait(1)
if (string.find(actor.class, "sorcerer") or string.find(actor.class, "pyromancer")) and actor.level > 72 then
    if (stage or 0) == 0 and (string.find(speech, "meteor") or string.find(speech, "meteors") or string.find(speech, "meteors?") or string.find(speech, "no")) then
        actor:send(tostring(self.name) .. " tells you, 'Yes, they are the culmination of my life's work.  They are the perfect balance of earth, fire, and air.'")
        wait(2)
        actor:send(tostring(self.name) .. " tells you, 'Now leave me to my fun.  I have a seagull to obliterate.'")
        wait(3)
        actor:send(tostring(self.name) .. " tells you, 'If you like, you may stand by and observe.'")
        wait(3)
        self.room:send(tostring(self.name) .. " starts casting '<b:yellow>celneptin</>'...")
        wait(2)
        run_room_trigger(481, 157)
        wait(3)
        self:command("sigh")
        actor:send(tostring(self.name) .. " tells you, 'I suppose you wish to do more than observe, am I right?  " .. tostring(actor.name) .. ", would you like to try to learn this rather difficult spell?'")
    elseif string.find(speech, "yes") then
        if actor:get_quest_var("meteorswarm:new") ~= "no" then
            self:say("Show me the meteorite.")
        elseif (stage or 0) == 0 then
            actor:start_quest("meteorswarm")
            actor:send(tostring(self.name) .. " tells you, 'Yes, well first you need a powerful piece of earth.  Not just any rock will do.  It needs to be positively alive with great energy.'")
            wait(2)
            self:command("consider " .. tostring(actor))
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'I doubt that you would be able to summon such earth yourself...  At least, not until you have mastered the element.'")
            wait(5)
            self:command("ponder")
            wait(4)
            actor:send(tostring(self.name) .. " tells you, 'There was once a powerful mage that created a massive guardian of stone to bar the way into the Nine Hells.  Such a creature would be a perfect source of powerfully imbued earth.'")
            self:command("dream")
            wait(3)
            actor:send(tostring(self.name) .. " tells you, 'Unfortunately, I do not know where the location of that entry is.  But I know someone who might.'")
            wait(1)
            self:command("grumble")
            wait(5)
            actor:send(tostring(self.name) .. " tells you, 'There's a drunken lout, goes by the name Jemnon the Lionhearted.'")
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'His exploits are as idiotic as the greatest heroes are brave.  While he causes far more problems than he solves, he has stumbled upon more secret knowledge than I care to admit.'")
            wait(3)
            actor:send(tostring(self.name) .. " tells you, 'He may very well know the location of this rocky behemoth.'")
            wait(5)
            actor:send(tostring(self.name) .. " tells you, 'Your first challenge will be <b:cyan>locating Jemnon</>.  He's almost certainly drinking himself stupid in a <b:cyan>bar</> or <b:cyan>tavern</> somewhere.  If you do find him, you'll have to <b:cyan>ask him about the rock monster</>.'")
            -- TODO(parity): bar_num is a legacy 5-digit room vnum. The
            -- meteorswarm quest still tracks it as a single integer var.
            -- Preserved as-is until the quest var schema can be revisited.
            local roll = random(1, 13)
            local bar_num
            if roll == 1 then
                -- Tavern of the Fallen Star in Southern Borderhold
                bar_num = 2334
            elseif roll == 2 then
                -- Sloshed Squirrel in Mielikki
                bar_num = 3033
            elseif roll == 3 then
                -- Forest Tavern in Mielikki
                bar_num = 3053
            elseif roll == 4 then
                -- Ole Witch Tavern in Anduin
                bar_num = 6037
            elseif roll == 5 then
                -- Phillips Backdoor Bar in Anduin
                bar_num = 6044
            elseif roll == 6 then
                -- Red Feathered Nest Anduin
                bar_num = 6054
            elseif roll == 7 then
                -- Shawns Tavern in Anduin
                bar_num = 6112
            elseif roll == 8 then
                -- Drunken Ogre Inn in Anduin
                bar_num = 6131
            elseif roll == 9 then
                -- Golden Goblet Inn and Tavern in Anduin
                bar_num = 6226
            elseif roll == 10 then
                -- Karrs Pub in Ickle
                bar_num = 10029
            elseif roll == 11 then
                -- Mermaid's Tail in Ogakh
                bar_num = 30008
            elseif roll == 12 then
                -- Biergarten in Ogakh
                bar_num = 30089
            else
                -- Flirting Puppy
            end
            actor:set_quest_var("meteorswarm", "bar_num", bar_num)
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'You can check on your <b:cyan>[spell progress]</> with me at any time.'")
        elseif stage == 2 then
            actor:send(tostring(self.name) .. " tells you, 'Magnificent!  Bring back a piece of it as a magical focus and I can continue teaching you this spell.'")
        elseif stage == 3 then
            actor:send(tostring(self.name) .. " tells you, 'Splendid!  May I see it?'")
            wait(2)
        elseif stage == 4 then
            actor:set_quest_var("meteorswarm", "fire", 2)
            actor:send(tostring(self.name) .. " tells you, 'The last element you must master is the sky itself.  But this must be no mere demonstration of the power of flight, or even a large gust of wind.'")
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'No, in order to understand the sheer magnitude of energy involved, you will need to learn from a true master of air.'")
            wait(3)
            actor:send(tostring(self.name) .. " tells you, 'But who would be most appropriate...?'")
            self:command("think")
            wait(4)
            actor:send(tostring(self.name) .. " tells you, 'Wait, I've got it!  It's a long shot...'")
            wait(1)
            actor:send(tostring(self.name) .. " tells you, 'But...'")
            wait(1)
            actor:send(tostring(self.name) .. " tells you, 'You should <b:cyan>meet with the dragon who created the floating fortress in southern Caelia</>.'")
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'Ask him to teach you.  And be certain to show him the proper respect when you do!'")
            wait(2)
            actor:send(tostring(self.name) .. " tells you, 'Good luck!  You'll need it...'")
        elseif stage == 5 then
            actor:send(tostring(self.name) .. " tells you, 'Let me check the meteorite.'")
        end
    end
end$trig$, '91247fe509be69086b9305bc3a073556'),
