  -- data/triggers/584/584_01_princess_receive.lua
  (584, 1, $trig$-- Only react when the swan feathers are received.
if not (object.zone_id == 584 and object.local_id == 17) then
    return true
end

wait(1)
self.room:send(tostring(self.name) .. " sighs in great relief.")
wait(2)
self:say("Thank you from the bottom of my heart, kind adventurer.")
self:say("Your deeds shall not go unrewarded.")
wait(2)
self:destroy_item("feathers")
self.room:spawn_object(584, 1)
self:command("give feather " .. tostring(actor.name))

-- Credit every grouped player still in the room with the "feather" step;
-- fall back to crediting the lone actor if they are not in a group.
local size = actor.group_size or 0
if size > 0 then
    for i = 1, size do
        local person = actor.group_member[i]
        if person and person.room == self.room then
            if person:get_quest_stage("kod_quest") == 0 then
                person:start_quest("kod_quest")
            end
            person:set_quest_var("kod_quest", "feather", 1)
        end
    end
else
    if actor:get_quest_stage("kod_quest") == 0 then
        actor:start_quest("kod_quest")
    end
    actor:set_quest_var("kod_quest", "feather", 1)
end$trig$, 'e2442ced5ecc9cf752ec1afcb9c3ecd8'),
  -- data/triggers/584/584_04_unicorn_girl_receive.lua
  (584, 4, $trig$-- Only react when the legal writ is received.
if not (object.zone_id == 584 and object.local_id == 35) then
    return true
end

wait(1)
self:destroy_item("legal")
self.room:send(tostring(self.name) .. " begins to sob hysterically.")
self:say("Thank you, thank you so very much!")
wait(2)
self:command("rem fetter")
self:command("drop fetter")
self:say("I am free!")
wait(2)
self:say("Please accept this gift, as reward for setting me free.")
wait(2)
self.room:send("The slave girl pulls a necklace with a spiral horn from her tattered clothes.")
wait(2)
self.room:spawn_object(584, 29)
self:command("give alicorn " .. tostring(actor.name))
wait(2)
self:say("I must return to my family!")
self.room:send("The slave girl quickly runs away!")

-- Credit every grouped player still in the room with the "alicorn" step;
-- fall back to crediting the lone actor if they are not in a group.
local size = actor.group_size or 0
if size > 0 then
    for i = 1, size do
        local person = actor.group_member[i]
        if person and person.room == self.room then
            if person:get_quest_stage("kod_quest") == 0 then
                person:start_quest("kod_quest")
            end
            person:set_quest_var("kod_quest", "alicorn", 1)
        end
    end
else
    if actor:get_quest_stage("kod_quest") == 0 then
        actor:start_quest("kod_quest")
    end
    actor:set_quest_var("kod_quest", "alicorn", 1)
end

world.destroy(self)$trig$, 'd76e70190b4e400e77e9f1b401abba32'),
  -- data/triggers/590/590_07_dark_robed_yes.lua
  (590, 7, $trig$-- Converted from DG Script #59007: dark_robed_yes
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: yes
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "yes") then
    return true  -- No matching keywords
end
wait(3)
-- Walk the speaker's group; start the Sacred Haven quest for any evil-aligned
-- members co-located with the dark adept. Continue with the dialogue if at
-- least one member qualifies (matches the speaker's own group).
local continue = false
for _, person in ipairs(actor.group or { actor }) do
    if person.room == self.room and person.alignment <= -350 then
        continue = true
        if person:get_quest_stage("sacred_haven") == 0 then
            person:start_quest("sacred_haven")
            person:send("<b:white>You have begun the Sacred Haven quest!</>")
        end
    end
end
if continue then
    actor:send(tostring(self.name) .. " steps in closer towards you and rests his hand on your shoulder.")
    self.room:send_except(actor, tostring(self.name) .. " steps in closer towards " .. tostring(actor.name) .. " and rests its hand on " .. tostring(actor.possessive) .. " shoulder.")
    wait(6)
    actor:send(tostring(self.name) .. " tells you, 'Bring me an adornment of light from one of the sanctuary priests and I will be convinced that you are capable enough that my key will not be wasted.'")
    wait(6)
    actor:send(tostring(self.name) .. " tells you, 'Ask me <b:white>[what am I doing?]</> if you forget.'")
    wait(9)
    self.room:send(tostring(self.name) .. " says, 'Now be gone with you, and hurry before they destroy my artifacts.'")
end$trig$, 'c0ca6d10ede38537b152f1eb5af67ffd'),
  -- data/triggers/615/615_71_niaxxa_death.lua
  (615, 71, $trig$-- Converted from DG Script #61571: Niaxxa death
-- Original: MOB trigger, flags: DEATH, probability: 100%
-- Award the Enchanted Hollow quest to every group-mate of the killer
-- who is in this room.
local size = actor.group_size or 0
if size > 0 then
    for a = 1, size do
        local person = actor.group_member and actor.group_member[a]
        if person and person.room == self.room then
            if person:get_quest_stage("enchanted_hollow_quest") > 0 and not person:get_has_completed("enchanted_hollow_quest") then
                person:complete_quest("enchanted_hollow_quest")
            end
        end
    end
elseif actor.room == self.room then
    if actor:get_quest_stage("enchanted_hollow_quest") > 0 and not actor:get_has_completed("enchanted_hollow_quest") then
        actor:complete_quest("enchanted_hollow_quest")
    end
end$trig$, 'da08bbc6ee40ab7d786df719b6ea79ce'),
  -- data/triggers/625/625_19_rhell_merchant_refuse.lua
  (625, 19, $trig$-- Converted from DG Script #62519: Rhell merchant refuse
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
local response
if actor:get_has_completed("ursa_quest") then
    response = "I don't really need this."
elseif actor:get_quest_stage("ursa_quest") == 0 or actor:get_quest_stage("ursa_quest") == 0 then
    response = "I don't think this will help me."
elseif actor:get_quest_stage("ursa_quest") == 1 then
    -- Three letter-objects (625, 10/11/12) advance the quest; pass them through.
    if object.zone_id == 625 and (object.local_id == 10 or object.local_id == 11 or object.local_id == 12) then
        return true
    else
        response = "This isn't helpful."
    end
end
if not response then
    return true
end
self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
wait(1)
self:say(tostring(response))
if actor:get_quest_stage("ursa_quest") == 1 then
    wait(2)
    self:say("Maybe you could ask someone who might know.")
end
return true$trig$, 'c7633baa25a05b96d3a065f818754767')
) AS v(zone_id, id, commands, old_md5)
WHERE t.zone_id = v.zone_id
  AND t.id = v.id
  AND md5(t.commands) = v.old_md5
  AND t.commands IS DISTINCT FROM v.commands;

COMMIT;
